import {KOLOM_SCENES,kolomAvailable,kolomLocal} from './kolomenskaya.js';
import {ITEMS} from './data.js';
export function kolomEntry(s,{btn}){
 if(!kolomAvailable(s)&&s.interactiveMission?.id!=='kolomenskaya')return '';
 return '<section class="card"><svg viewBox="0 0 100 100" width="60" height="60" aria-label="Дима Лось"><rect width="100" height="100" rx="12" fill="#bcbda7"/><path d="M12 100V75Q50 48 88 75V100" fill="#434b39"/><ellipse cx="50" cy="42" rx="24" ry="29" fill="#d6c4a1" stroke="#222" stroke-width="3"/><path d="M26 26h48L66 9H34Z" fill="#535d43"/><text x="50" y="23" text-anchor="middle" fill="#ddd">М</text><path d="M36 42h5m18 0h5M42 59h16" stroke="#222" stroke-width="3"/></svg><h3>Дима Лось</h3><p class="subtitle">Начальник охраны Технопарка</p><p>С Коломенской снова лезут скорпионы-пауки. Помоги очистить станцию.</p>'+btn(s.interactiveMission?.id==='kolomenskaya'?'Продолжить очистку Коломенской':s.completedLocations?.kolomenskaya?'Очистка Коломенской · повтор для теста':'Очистка Коломенской','kolomOpen','','full mission-start')+(kolomLocal()?'<p class="note">Подземная вылазка · Технопарк → Коломенская · локальный пробный проход, черновые иллюстрации</p>':'')+'</section>';
}
export function kolomBody(s,{btn,esc,health,heroPortrait,renderLog}){
 const a=s.interactiveMission;
 if(a?.id!=='kolomenskaya'){
  if(s.lastKolomMission&&!s.kolomPreparing){const r=s.lastKolomMission;return '<h3>'+(r.success?'Коломенская освобождена':r.dead?'Герой погиб':'Возвращение без завершения')+'</h3>'+(r.heroes??[r.hero]).map(h=>health(h)+'<p>'+esc(h.name)+' · XP '+(r.entries?.find(e=>e.id===h.id)?.xp??r.awardedXp??0)+'</p>').join('')+'<p>Опыт: '+(r.awardedXp??0)+' · Облучение: '+(r.radiationReceived??0)+'</p><p>'+Object.entries(r.loot).map(([id,n])=>esc(ITEMS[id].name)+' ×'+n).join(', ')+'</p><p>'+(r.repeat?'Тестовый повтор: сохраняется только опыт.':'Награды учтены при возвращении.')+'</p>'+btn('Вернуться на станцию','kolomClose','','full');}
  if(!s.kolomQuestAccepted)return '<h3>Дима Лось · Очистка Коломенской</h3><p>Оттуда всё время лезут пауки. Наши уже устали их отгонять. Проверь тоннели и очисти станцию.</p>'+btn('Принять задание','kolomAccept','','full mission-start');
  const heroes=s.heroes.filter(h=>!h.dead&&!h.unconscious&&!h.job&&!h.needsAdventureRest&&!h.adventureCooldownUntil);
  return '<p class="note">Сцена 02</p><img class="hansa-route-art" src="./kolom-scenes/prep.svg" alt="Выход из Технопарка"><h3>Подготовка · отряд из двух героев</h3><p>Фильтры не нужны. Рекомендован 7-й уровень. Пригодятся РАД-защита, Аптечка доктора и огонь. Потребуется суммарно 10 Молотовых либо 10 зарядов огнемёта (первое применение входит в эти десять), затем немедленно бой с маткой. Одиночный герой при Силе 0 от яда гибнет. В отряде напарник может спасти его после победы.</p><select id="kolom-hero" class="hero-select">'+heroes.map(h=>'<option value="'+esc(h.id)+'">'+esc(h.name)+' · ур. '+h.level+' · HP '+Math.round(h.hp)+' · Молотовы '+(h.molotovs??0)+' · патроны '+(h.heavyAmmo??0)+'</option>').join('')+'</select><label>Второй герой</label><select id="kolom-second" class="hero-select"><option value="">Идти одному — крайне опасно</option>'+heroes.map((h,i)=>'<option value="'+esc(h.id)+'" '+(i===1?'selected':'')+'>'+esc(h.name)+' · ур. '+h.level+'</option>').join('')+'</select><p><label><input id="kolom-risk" type="checkbox"> Подтверждаю риск для героя ниже 7-го уровня</label></p>'+btn('Снарядить лекарствами','kolomPack','data-category="medicine"','secondary')+btn('Снарядить гранатами','kolomPack','data-category="grenades"','secondary')+btn('Подтвердить отправку · без фильтров','kolomStart',heroes.length?'':'disabled','full mission-start');
 }
 const party=a.heroIds.map(id=>s.heroes.find(h=>h.id===id)),h=party.find(h=>h.id===a.selectedHealHeroId)??party.find(h=>h.hp>0)??party[0],total=key=>party.filter(h=>h.hp>0).reduce((n,h)=>n+(h[key]??0),0),node=a.node,scene=KOLOM_SCENES[node],b=(text,choice,disabled=false)=>btn(text,'kolomChoice',`data-node="${node}" data-choice="${choice}" data-target="${h.id}" ${disabled?'disabled':''}`,'full secondary');
 let choices='';
 if(node==='fork')choices=b('Прислушаться к чутью · ВОС 15','sense',a.senseUsed)+b('Левый тоннель','left')+b('Правый тоннель','right');
 if(['dry1','dry2','clear','blaze'].includes(node))choices=b('Продолжить путь','forward');
 if(['corpse','lair'].includes(node))choices=b('Обыскать останки','search')+b('Пройти мимо','skip');
 if(node==='anomaly')choices=b(party.some(member=>['medium','heavy'].includes(ITEMS[member.body]?.armorClass))?'Спрятаться за вагонеткой · ИНТ 18, затем ЛОВ 13':'Убежать от аномалии','avoid');
 if(node==='wet')choices=b('Идти дальше · участок 4 РАД','forward')+b('Вернуться к развилке','back');
 if(['worm','boss'].includes(node))choices=b('Вступить в бой','fight');
 if(node==='station')choices=b('Пробиваться и искать решение','enter');
 if(node==='pressure')choices=b('Стрелять и искать решение · ИНТ 14','think')+(a.ideas>=1?b('Отогнать гранатой','grenade',!['grenades','tinGrenades','lu216Grenades','dynamites'].some(k=>total(k)>0))+b('Использовать Молотов · −1 шт.','molotov',!total('molotovs')):'')+(a.ideas>=2?b('Использовать тяжёлое оружие','heavy',!party.some(member=>member.hp>0&&ITEMS[member.rangedWeapon]?.usesHeavyAmmo&&member.heavyAmmo>0)):'');
 if(node==='fire'){const fc=a.fireDemonstration==='flame'?9:10,mc=a.fireDemonstration==='molotov'?9:10;choices=b('Спалить гнёзда · −'+fc+' зарядов огнемёта или −'+mc+' Молотовых','burn',party.filter(h=>h.hp>0&&ITEMS[h.rangedWeapon]?.flame).reduce((n,h)=>n+(h.heavyAmmo??0),0)<fc&&total('molotovs')<mc);}
 if(node==='casualty')choices=b('Сбежать с выжившим, бросив поверженного','escape')+b('Драться до последнего','fight');
 if(node==='combat')choices=b('Следующий ход','turn')+b('Разыграть бой до исхода','auto');
 if(node==='recovery')choices='<p>Лечим: '+esc(h.name)+' — выбери портрет героя.</p>'+[['doctorKit','doctorKits'],['medicKit','medicKits'],['dressingKit','dressingKits'],['bandage','bandages']].filter(([,key])=>total(key)>0).map(([id,key])=>b(ITEMS[id].name+' · '+total(key),'heal:'+id)).join('')+(party.some(h=>h.hp>0&&['medic','doctor'].includes(h.profession))?b('Лечение специалистом · −1 Силы','treatment',a.treatmentUsed)+b('Снять 1–3 дозы яда · −1 Силы','antidote',a.treatmentUsed||!h.poisonDoses):'')+b('Продолжить путь','continue');
 if(node==='cleanup')choices=b('Осмотреть и дочистить станцию','search');
 if(node==='final')choices=b('Завершить вылазку и сдать задание','finish');
 const fight=a.combat,art=node==='combat'?'combat-'+(fight.enemies.some(e=>e.kolomQueen)?'queen':fight.enemies.some(e=>e.kolomSlime)?'worm':'spiders'):['recovery','casualty'].includes(node)?'recovery':node;
 return '<p class="note">Сцена '+scene[0]+' · '+esc(h.name)+' · Участок '+a.locationRadiation+' РАД</p><img class="hansa-route-art" src="./kolom-scenes/'+art+'.svg" alt="'+esc(scene[1])+'"><h3>'+scene[1]+'</h3><p>'+scene[2]+'</p>'+party.map(member=>'<button class="offer" data-action="kolomChoice" data-node="'+node+'" data-choice="pick" data-target="'+member.id+'">'+heroPortrait(member)+health(member)+'<span>'+esc(member.name)+' · Отравление '+(member.poisonDoses??0)+'</span></button>').join('')+'<p class="warning">Отравление: '+(h.poisonDoses??0)+' · Патроны: '+(h.heavyAmmo??0)+' · Молотовы: '+(h.molotovs??0)+'</p>'+(node==='combat'?'<div class="card"><strong>Бой · JRPG</strong><p>Инициатива: '+fight.order.map(x=>esc(x.name)).join(' → ')+'</p>'+fight.enemies.map(e=>'<p>'+esc(e.name)+' · '+Math.max(0,Math.round(e.hp))+' HP</p>').join('')+'<section class="battle-log">'+renderLog(fight.events)+'</section></div>':'')+'<div class="note">'+a.events.slice(-5).map(t=>'<p>'+esc(t)+'</p>').join('')+'</div><div class="research-options">'+choices+b('Отступить на станцию','retreat')+'</div>';
}
